"use client";

import { Sequencer as SequencerPrimitive } from "@audio-ui/react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

/** Mirrors the primitive's own default step count, used only to keep the grid from collapsing when neither value nor defaultValue is passed. */
const DEFAULT_STEPS = 16;

const sequencerVariants = cva("", {
  defaultVariants: {
    size: "default",
  },
  variants: {
    size: {
      default: "gap-1 p-1",
      lg: "gap-1.5 p-1.5",
      sm: "gap-0.5 p-0.5",
    },
  },
});

interface SequencerProps
  extends SequencerPrimitive.RootProps,
    VariantProps<typeof sequencerVariants> {}

export function Sequencer({
  className,
  size,
  value,
  defaultValue,
  ...props
}: SequencerProps) {
  const columns = (value ?? defaultValue)?.[0]?.length ?? DEFAULT_STEPS;

  return (
    <SequencerPrimitive.Root
      className="w-full data-[disabled=true]:cursor-not-allowed"
      defaultValue={defaultValue}
      value={value}
      {...props}
    >
      <SequencerPrimitive.Track
        className={cn(
          "rounded-none border border-transparent bg-card shadow-sm ring-1 ring-foreground/10 transition-[color,border-color,box-shadow,opacity] duration-150 ease-out hover:ring-2 hover:ring-ring/30 has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring/30 active:ring-2 active:ring-ring/30 has-[:focus-visible]:border-ring active:border-ring motion-reduce:transition-none mx-auto grid w-full touch-none select-none",
          "focus-visible:outline-none",
          "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
          sequencerVariants({ size }),
          className
        )}
        data-slot="sequencer"
        style={{
          gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
        }}
      >
        <SequencerPrimitive.Cells>
          {(_state, row, column) => (
            <SequencerPrimitive.Cell
              className="rounded-none bg-input/70 transition-[background-color,box-shadow] duration-150 ease-out hover:ring-2 hover:ring-ring/30 focus-visible:ring-2 focus-visible:ring-ring/30 active:ring-2 active:ring-ring/30 data-[active-step=true]:ring-2 data-[active-step=true]:ring-ring data-[state=on]:bg-primary motion-reduce:transition-none aspect-square cursor-pointer outline-none"
              column={column}
              key={`sequencer-cell-${row}-${column}`}
              row={row}
            />
          )}
        </SequencerPrimitive.Cells>
      </SequencerPrimitive.Track>
    </SequencerPrimitive.Root>
  );
}
